pub(super) fn job_title(random: &FakerRandom, locale: &str) -> String {
    let titles = match locale {
        "de_DE" => DE_DE,
        "fr_FR" | "fr_BE" | "fr_CA" | "fr_CH" => FR_FR,
        "id_ID" => ID_ID,
        "nb_NO" => NB_NO,
        "nl_NL" => NL_NL,
        "ru_RU" => RU_RU,
        "sv_SE" => SV_SE,
        "tr_TR" => TR_TR,
        "uk_UA" => UK_UA,
        // Local Company providers without their own job list inherit Lorem::word.
        "ar_EG" | "ar_JO" | "ar_SA" | "bn_BD" | "cs_CZ" | "da_DK" | "de_AT" | "de_CH" | "el_CY"
        | "el_GR" | "en_GB" | "en_ZA" | "es_AR" | "es_ES" | "es_PE" | "es_VE" | "fa_IR"
        | "fi_FI" | "he_IL" | "hr_HR" | "hu_HU" | "hy_AM" | "is_IS" | "it_CH" | "it_IT"
        | "ja_JP" | "ka_GE" | "kk_KZ" | "ko_KR" | "lt_LT" | "me_ME" | "ms_MY" | "nl_BE"
        | "pl_PL" | "pt_BR" | "pt_PT" | "sk_SK" | "sl_SI" | "th_TH" | "zh_CN" | "zh_TW" => {
            LOREM_WORDS
        }
        _ => EN_US,
    };
    random.sample(titles).to_owned()
}
